constraints:
1 ≤ Number of nodes ≤ 10^{3}

expected time complexity: O(n)
expected auxiliary space: O(1)

standard_solution_code:
class Solution:

	def inorder(self, root):
		if root is None:
			return
		self.inorder(root.left)
		if self.prev is None:
			self.prev = root
		else:
			if self.prev.data > root.data:
				self.possibles.append(self.prev)
				self.possibles.append(root)
			self.prev = root
		if len(self.possibles) == 4:
			return
		self.inorder(root.right)

	def correctBST(self, root):
		self.prev = None
		self.possibles = []
		self.inorder(root)
		node1 = self.possibles[0]
		node2 = self.possibles[-1]
		(node1.data, node2.data) = (node2.data, node1.data)
		return root
